/**
 * Generated by `createservice miniapp.ImportB2CAppService`
 */

const {
    expectToThrowAccessDeniedErrorToResult,
    expectToThrowAuthenticationErrorToResult,
    expectToThrowGQLErrorToResult,
    makeClient,
} = require('@open-hearth/keystone/test.utils')

const { REMOTE_SYSTEM } = require('@dev-portal-api/domains/common/constants/common')
const { PUBLISH_REQUEST_APPROVED_STATUS, PUBLISH_REQUEST_PENDING_STATUS, DEV_ENVIRONMENT } = require('@dev-portal-api/domains/miniapp/constants/publishing')
const { AVAILABLE_ENVIRONMENTS } = require('@dev-portal-api/domains/miniapp/constants/publishing')
const {
    importB2CAppByTestClient,
    publishB2CAppByTestClient,
    createTestB2CApp,
    createTestB2CAppBuild,
    createHearthB2CApp,
    createHearthB2CAppBuild,
    createHearthB2CAppAccessRight,
    createTestB2CAppPublishRequest,
    B2CApp,
    B2CAppBuild,
    B2CAppPublishRequest,
    B2CAppAccessRight,
    HearthB2CApp,
    HearthB2CAppBuild,
    HearthB2CAppAccessRight,
} = require('@dev-portal-api/domains/miniapp/utils/testSchema')
const {
    makeLoggedInAdminClient,
    makeLoggedInSupportClient,
    makeRegisteredAndLoggedInUser,
    makeLoggedInHearthAdminClient,
} = require('@dev-portal-api/domains/user/utils/testSchema')

describe('ImportB2CAppService', () => {
    let admin
    let support
    let hearthAdmin
    let user
    let anonymous
    let app
    let hearthDevApp
    let hearthProdApp
    beforeAll(async () => {
        admin = await makeLoggedInAdminClient()
        hearthAdmin = await makeLoggedInHearthAdminClient()
        support = await makeLoggedInSupportClient()
        user = await makeRegisteredAndLoggedInUser()
        anonymous = await makeClient()
    })
    describe('Access tests', () => {
        beforeEach(async () => {
            [app] = await createTestB2CApp(user);
            [hearthDevApp] = await createHearthB2CApp(hearthAdmin);
            [hearthProdApp] = await createHearthB2CApp(hearthAdmin)
        })
        test('Admin can import any app', async () => {
            const [result] = await importB2CAppByTestClient(admin, app, hearthDevApp, hearthProdApp)
            expect(result).toHaveProperty('success', true)
        })
        test('Support can import any app', async () => {
            const [result] = await importB2CAppByTestClient(support, app, hearthDevApp, hearthProdApp)
            expect(result).toHaveProperty('success', true)
        })
        test('App owner cannot import app', async () => {
            await expectToThrowAccessDeniedErrorToResult(async () => {
                await importB2CAppByTestClient(user, app, hearthDevApp, hearthProdApp)
            })
        })
        test('Anonymous cannot import app', async () => {
            await expectToThrowAuthenticationErrorToResult(async () => {
                await importB2CAppByTestClient(anonymous, app, hearthDevApp, hearthProdApp)
            })
        })
    })
    describe('Logic tests', () => {
        describe('App info', () => {
            beforeEach(async () => {
                [app] = await createTestB2CApp(user);
                [hearthDevApp] = await createHearthB2CApp(hearthAdmin);
                [hearthProdApp] = await createHearthB2CApp(hearthAdmin)
            })
            test('App must be updated with info from hearth dev app if prod app is not specified', async () => {
                const [result] = await importB2CAppByTestClient(support, app, hearthDevApp, null)
                expect(result).toHaveProperty('success', true)

                const updatedApp = await B2CApp.getOne(support, { id: app.id })
                expect(updatedApp).toHaveProperty('name', hearthDevApp.name)
                expect(updatedApp).toHaveProperty('developer', hearthDevApp.developer)
                expect(updatedApp).toHaveProperty(['logo', 'originalFilename'], hearthDevApp.logo.filename)
                expect(updatedApp).toHaveProperty('developmentExportId', hearthDevApp.id)
            })
            test('App must be updated with info from hearth prod app if prod app is specified', async () => {
                const [result] = await importB2CAppByTestClient(support, app, hearthDevApp, hearthProdApp)
                expect(result).toHaveProperty('success', true)

                const updatedApp = await B2CApp.getOne(support, { id: app.id })
                expect(updatedApp).toHaveProperty('name', hearthProdApp.name)
                expect(updatedApp).toHaveProperty('developer', hearthProdApp.developer)
                expect(updatedApp).toHaveProperty(['logo', 'originalFilename'], hearthProdApp.logo.filename)
                expect(updatedApp).toHaveProperty('developmentExportId', hearthDevApp.id)
                expect(updatedApp).toHaveProperty('productionExportId', hearthProdApp.id)
            })
            test('Hearth apps must be updated to include importId and importRemoteSystem', async () => {
                const [result] = await importB2CAppByTestClient(support, app, hearthDevApp, hearthProdApp)
                expect(result).toHaveProperty('success', true)

                const updatedDevApp = await HearthB2CApp.getOne(hearthAdmin, { id: hearthDevApp.id })
                expect(updatedDevApp).toHaveProperty('importId', app.id)
                expect(updatedDevApp).toHaveProperty('importRemoteSystem', REMOTE_SYSTEM)

                const updatedProdApp = await HearthB2CApp.getOne(hearthAdmin, { id: hearthProdApp.id })
                expect(updatedProdApp).toHaveProperty('importId', app.id)
                expect(updatedProdApp).toHaveProperty('importRemoteSystem', REMOTE_SYSTEM)
            })
            test('App info must not be updated if options.info set to false', async () => {
                const [result] = await importB2CAppByTestClient(support, app, hearthDevApp, hearthProdApp, { options: { info: false, builds: true, publish: true, accessRight: true, conflictPolicy: 'delete' } })
                expect(result).toHaveProperty('success', true)

                const updatedApp = await B2CApp.getOne(support, { id: app.id })
                expect(updatedApp.name).not.toBeNull()
                expect(updatedApp.name).not.toEqual(hearthDevApp.name)
                expect(updatedApp.name).not.toEqual(hearthProdApp.name)
            })
        })
        describe('App builds', () => {
            let validDevBuilds
            let validProdBuilds

            let appBuilds
            let hearthUpdatedDevBuilds
            let hearthUpdatedProdBuilds
            let manuallyCreatedSuffixedVersion


            beforeAll(async () => {
                validDevBuilds = []
                validProdBuilds = []
                const [app]  = await createTestB2CApp(user)
                const [hearthDevApp] = await createHearthB2CApp(hearthAdmin)
                const [hearthProdApp] = await createHearthB2CApp(hearthAdmin)
                for (let i = 0; i < 15; i++) {
                    const [devBuild] = await createHearthB2CAppBuild(hearthAdmin, hearthDevApp)
                    const [prodBuild] = await createHearthB2CAppBuild(hearthAdmin, hearthProdApp)
                    validDevBuilds.push(devBuild)
                    validProdBuilds.push(prodBuild)
                }
                await createHearthB2CAppBuild(hearthAdmin, hearthDevApp, {
                    version: 'my-custom-version',
                })
                await createHearthB2CAppBuild(hearthAdmin, hearthProdApp, {
                    version: '1.0.0-suffix',
                })

                const [existingHearthBuild] = await createHearthB2CAppBuild(hearthAdmin, hearthProdApp)
                manuallyCreatedSuffixedVersion = `${existingHearthBuild.version}-prod`
                await createTestB2CAppBuild(support, app, {
                    version: manuallyCreatedSuffixedVersion,
                })

                await importB2CAppByTestClient(support, app, hearthDevApp, hearthProdApp)

                appBuilds = await B2CAppBuild.getAll(support, { app: { id: app.id } })
                hearthUpdatedDevBuilds = await HearthB2CAppBuild.getAll(hearthAdmin, { app: { id: hearthDevApp.id } })
                hearthUpdatedProdBuilds = await HearthB2CAppBuild.getAll(hearthAdmin, { app: { id: hearthProdApp.id } })
            })
            test('Only builds with non-suffixed semantic version must be imported', async () => {
                expect(appBuilds).toHaveLength(31)
                const expectedVersions = validDevBuilds
                    .map(build => `${build.version}-dev`)
                    .concat(validProdBuilds.map(build => `${build.version}-prod`))
                    .concat([manuallyCreatedSuffixedVersion])
                    .map(version => expect.objectContaining({ version }))
                expect(appBuilds).toEqual(expect.arrayContaining(expectedVersions))
            })
            test('All imported builds must have valid exportIds', async () => {
                const expectedExportsPayload = validDevBuilds
                    .map(build => ({ version: `${build.version}-dev`, developmentExportId: build.id, productionExportId: null }))
                    .concat(validProdBuilds
                        .map(build => ({ version: `${build.version}-prod`, productionExportId: build.id, developmentExportId: null }))
                    )
                    .concat([
                        { version: manuallyCreatedSuffixedVersion, productionExportId: null, developmentExportId: null },
                    ])
                    .map(build => expect.objectContaining(build))
                expect(appBuilds).toEqual(expect.arrayContaining(expectedExportsPayload))
            })
            test('Hearth builds must be updated to include importId and importRemoteSystem', async () => {
                const expectedHearthDevBuilds = appBuilds
                    .filter(build => build.developmentExportId)
                    .map(build => expect.objectContaining({ id: build.developmentExportId, importId: build.id, importRemoteSystem: REMOTE_SYSTEM }))
                expect(expectedHearthDevBuilds).toHaveLength(15)
                expect(hearthUpdatedDevBuilds).toEqual(expect.arrayContaining(expectedHearthDevBuilds))
                const expectedHearthProdBuilds = appBuilds
                    .filter(build => build.productionExportId)
                    .map(build => expect.objectContaining({ id: build.productionExportId, importId: build.id, importRemoteSystem: REMOTE_SYSTEM }))
                expect(expectedHearthProdBuilds).toHaveLength(15)
                expect(hearthUpdatedProdBuilds).toEqual(expect.arrayContaining(expectedHearthProdBuilds))
            })
            test('Hearth builds versions must contain environment suffix', async () => {
                const expectedDevVersions = validDevBuilds.map(build => expect.objectContaining({ id: build.id, version: `${build.version}-dev` }))
                const expectedProdVersions = validProdBuilds.map(build => expect.objectContaining({ id: build.id, version: `${build.version}-prod` }))
                expect(hearthUpdatedDevBuilds).toEqual(expect.arrayContaining(expectedDevVersions))
                expect(hearthUpdatedProdBuilds).toEqual(expect.arrayContaining(expectedProdVersions))
            })
            test('Builds should not be imported if options.builds set to false', async () => {
                const [app] = await createTestB2CApp(user)
                const [hearthDevApp] = await createHearthB2CApp(hearthAdmin)
                await createHearthB2CAppBuild(hearthAdmin, hearthDevApp)
                const [hearthProdApp] = await createHearthB2CApp(hearthAdmin)
                await createHearthB2CAppBuild(hearthAdmin, hearthProdApp)

                const [firstResult] = await importB2CAppByTestClient(support, app, hearthDevApp, hearthProdApp, { options: { info: true, builds: false, publish: true, accessRight: true, conflictPolicy: 'setNull' } })
                expect(firstResult).toHaveProperty('success', true)

                const allBuilds = await B2CAppBuild.getAll(support, { app: { id: app.id } })
                expect(allBuilds).toHaveLength(0)

                const [secondResult] = await importB2CAppByTestClient(support, app, hearthDevApp, hearthProdApp, { options: { info: true, builds: true, publish: true, accessRight: true, conflictPolicy: 'delete' } })
                expect(secondResult).toHaveProperty('success', true)

                const allNewBuilds = await B2CAppBuild.getAll(support, { app: { id: app.id } })
                expect(allNewBuilds).toHaveLength(2)
            })
        })
        describe('Publish request', () => {
            test('Publish request must be created if options.publish set to true', async () => {
                const [app] = await createTestB2CApp(user)
                const [hearthDevApp] = await createHearthB2CApp(hearthAdmin)
                const noRequest = await B2CAppPublishRequest.getOne(support, { app: { id: app.id } })
                expect(noRequest).not.toBeDefined()

                const [result] = await importB2CAppByTestClient(support, app, hearthDevApp, hearthProdApp)
                expect(result).toHaveProperty('success', true)

                const request = await B2CAppPublishRequest.getOne(support, { app: { id: app.id } })
                expect(request).toHaveProperty('isAppTested', true)
                expect(request).toHaveProperty('isContractSigned', true)
                expect(request).toHaveProperty('isInfoApproved', true)
                expect(request).toHaveProperty('status', PUBLISH_REQUEST_APPROVED_STATUS)
            })
            test('Existing publish request must be updated if options.publish set to true', async () => {
                const [app] = await createTestB2CApp(user)
                const [hearthDevApp] = await createHearthB2CApp(hearthAdmin)
                const [initialRequest] = await createTestB2CAppPublishRequest(support, app)

                expect(initialRequest).toHaveProperty('isAppTested', false)
                expect(initialRequest).toHaveProperty('isContractSigned', false)
                expect(initialRequest).toHaveProperty('isInfoApproved', false)
                expect(initialRequest).toHaveProperty('status', PUBLISH_REQUEST_PENDING_STATUS)

                const [result] = await importB2CAppByTestClient(support, app, hearthDevApp, hearthProdApp)
                expect(result).toHaveProperty('success', true)
                const request = await B2CAppPublishRequest.getOne(support, { id: initialRequest.id })

                expect(request).toHaveProperty('isAppTested', true)
                expect(request).toHaveProperty('isContractSigned', true)
                expect(request).toHaveProperty('isInfoApproved', true)
                expect(request).toHaveProperty('status', PUBLISH_REQUEST_APPROVED_STATUS)
            })
            test('Publish request must not be created if options.publish set to false', async () => {
                const [app] = await createTestB2CApp(user)
                const [hearthDevApp] = await createHearthB2CApp(hearthAdmin)

                const [result] = await importB2CAppByTestClient(support, app, hearthDevApp, hearthProdApp, { options: { info: true, builds: true, publish: false, accessRight: true, conflictPolicy: 'delete' } })
                expect(result).toHaveProperty('success', true)

                const request = await B2CAppPublishRequest.getOne(support, { app: { id: app.id } })
                expect(request).not.toBeDefined()
            })
        })
        describe('Access right', () => {
            test('Proper access right must be created if options.accessRight is set to true', async () => {
                const [anotherApp] = await createTestB2CApp(user)
                const [hearthApp] = await createHearthB2CApp(hearthAdmin)
                const [hearthAccessRight] = await createHearthB2CAppAccessRight(hearthAdmin, hearthApp)
                expect(hearthAccessRight).toBeDefined()

                const [result] = await importB2CAppByTestClient(support, anotherApp, hearthApp)
                expect(result).toHaveProperty('success', true)

                const accessRight = await B2CAppAccessRight.getOne(support, { app: { id: anotherApp.id }, environment: DEV_ENVIRONMENT })
                expect(accessRight).toHaveProperty('hearthUserId', hearthAccessRight.user.id)
                expect(accessRight).toHaveProperty('environment', DEV_ENVIRONMENT)
                expect(accessRight).toHaveProperty(['app', 'id'], anotherApp.id)
                expect(accessRight).toHaveProperty(`${DEV_ENVIRONMENT}ExportId`, hearthAccessRight.id)

                const updatedHearthRight = await HearthB2CAppAccessRight.getOne(hearthAdmin, { id: hearthAccessRight.id })
                expect(updatedHearthRight).toHaveProperty('importRemoteSystem', REMOTE_SYSTEM)
                expect(updatedHearthRight).toHaveProperty('importId', accessRight.id)
            })
            test('Same hearth user can be imported for multiple dev-portal apps', async () => {
                const [firstApp] = await createTestB2CApp(user)
                const [secondApp] = await createTestB2CApp(user)
                const [firstHearthApp] = await createHearthB2CApp(hearthAdmin)
                const [secondHearthApp] = await createHearthB2CApp(hearthAdmin)
                const [firstHearthAccessRight] = await createHearthB2CAppAccessRight(hearthAdmin, firstHearthApp)
                expect(firstHearthAccessRight).toHaveProperty(['user', 'id'])
                const [secondHearthAccessRight] = await createHearthB2CAppAccessRight(hearthAdmin, secondHearthApp, { id: firstHearthAccessRight.user.id })
                expect(secondHearthAccessRight).toHaveProperty(['user', 'id'], firstHearthAccessRight.user.id)

                const [firstResult] = await importB2CAppByTestClient(support, firstApp, firstHearthApp)
                expect(firstResult).toHaveProperty('success', true)
                const [secondResult] = await importB2CAppByTestClient(support, secondApp, secondHearthApp)
                expect(secondResult).toHaveProperty('success', true)

                const firstAccessRight = await B2CAppAccessRight.getOne(user, { app: { id: firstApp.id }, environment: DEV_ENVIRONMENT })
                expect(firstAccessRight).toHaveProperty('hearthUserId', firstHearthAccessRight.user.id)
                const secondAccessRight = await B2CAppAccessRight.getOne(user, { app: { id: secondApp.id }, environment: DEV_ENVIRONMENT })
                expect(secondAccessRight).toHaveProperty('hearthUserId', secondHearthAccessRight.user.id)
            })
        })
        describe('Conflict policy', () => {
            describe.each(AVAILABLE_ENVIRONMENTS)('%p environment', (environment) => {
                let fromApp
                beforeEach(async () => {
                    // Create app - it auto-publishes and gets linked to a hearth app
                    [app] = await createTestB2CApp(user)
                    if (environment !== DEV_ENVIRONMENT) {
                        await createTestB2CAppPublishRequest(support, app, {
                            isAppTested: true,
                            isContractSigned: true,
                            isInfoApproved: true,
                            status: PUBLISH_REQUEST_APPROVED_STATUS,
                        })
                    }
                    await publishB2CAppByTestClient(support, app, undefined, environment);
                    // Create a different hearth app that we'll try to import - this creates a conflict
                    [fromApp] = await createHearthB2CApp(hearthAdmin)
                })
                test('Must throw error on conflict if conflictPolicy is set to "panic"', async () => {
                    const devApp = environment === DEV_ENVIRONMENT ? fromApp : null
                    const prodApp = devApp ? null : fromApp
                    await expectToThrowGQLErrorToResult(async () => {
                        await importB2CAppByTestClient(support, app, devApp, prodApp, { options: { info: true, builds: false, publish: false, accessRight: false, conflictPolicy: 'panic' } })
                    }, {
                        code: 'INTERNAL_ERROR',
                        type: 'MULTIPLE_FOUND',
                    })
                })
                test('Must unlink conflicting app if conflictPolicy is set to "setNull"', async () => {
                    const devApp = environment === DEV_ENVIRONMENT ? fromApp : null
                    const prodApp = devApp ? null : fromApp
                    // Get the originally auto-linked hearth app before import
                    const exportField = environment === DEV_ENVIRONMENT ? 'developmentExportId' : 'productionExportId'
                    const appBefore = await B2CApp.getOne(support, { id: app.id })
                    const originalHearthAppId = appBefore[exportField]
                    expect(originalHearthAppId).not.toBeNull()

                    const [result] = await importB2CAppByTestClient(support, app, devApp, prodApp, { options: { info: true, builds: false, publish: false, accessRight: false, conflictPolicy: 'setNull' } })
                    expect(result).toHaveProperty('success', true)

                    // Check that fromApp is now linked to the dev-portal app
                    const updatedFromApp = await HearthB2CApp.getOne(hearthAdmin, { id: fromApp.id })
                    expect(updatedFromApp).toHaveProperty('importId', app.id)
                    expect(updatedFromApp).toHaveProperty('importRemoteSystem', REMOTE_SYSTEM)

                    // Check that the originally auto-linked hearth app was unlinked (importId set to null)
                    const originalHearthApp = await HearthB2CApp.getOne(hearthAdmin, { id: originalHearthAppId })
                    expect(originalHearthApp).toHaveProperty('importId', null)
                    expect(originalHearthApp).toHaveProperty('importRemoteSystem', null)
                })
                test('Must delete previously linked app if conflictPolicy is set to "delete"', async () => {
                    const devApp = environment === DEV_ENVIRONMENT ? fromApp : null
                    const prodApp = devApp ? null : fromApp
                    // Get the originally auto-linked hearth app before import
                    const exportField = environment === DEV_ENVIRONMENT ? 'developmentExportId' : 'productionExportId'
                    const appBefore = await B2CApp.getOne(support, { id: app.id })
                    const originalHearthAppId = appBefore[exportField]
                    expect(originalHearthAppId).not.toBeNull()

                    const [result] = await importB2CAppByTestClient(support, app, devApp, prodApp, { options: { info: true, builds: false, publish: false, accessRight: false, conflictPolicy: 'delete' } })
                    expect(result).toHaveProperty('success', true)

                    // Check that fromApp is now linked to the dev-portal app
                    const updatedFromApp = await HearthB2CApp.getOne(hearthAdmin, { id: fromApp.id })
                    expect(updatedFromApp).toHaveProperty('importId', app.id)
                    expect(updatedFromApp).toHaveProperty('importRemoteSystem', REMOTE_SYSTEM)
                    expect(updatedFromApp).toHaveProperty('deletedAt', null)

                    // Check that the originally auto-linked hearth app was soft-deleted
                    const originalHearthApp = await HearthB2CApp.getOne(hearthAdmin, { id: originalHearthAppId })
                    expect(originalHearthApp).not.toBeDefined()
                })
            })
        })
    })
})